package cc.ataglace.molebutter.marketplace.api;
import org.junit.jupiter.api.Test;
import static org.assertj.core.api.Assertions.*;
import java.util.*;
import tools.jackson.databind.ObjectMapper;
class PartnerFormSupportTest {
    final ObjectMapper json=new ObjectMapper();
    final PartnerEditor.Schema schema=new PartnerEditor.Schema(List.of(new PartnerEditor.Field("name","상품명","상품 정보","text",true,List.of())),500,15,"");
    PartnerEditor.Input input(String name){return new PartnerEditor.Input(Map.of("name",name),List.of(new PartnerEditor.Option("00000000-0000-0000-0000-000000000001","기본 상품","","0","0",List.of(),true)),List.of(new PartnerEditor.Image("00000000-0000-0000-0000-000000000002",null,"https://images.example/1.png",true,0)),"<p>설명</p>","notice",List.of(new MarketplaceDrafts.Attribute("field","value")),List.of());}
    @Test void preservesExplicitEmptyAndZero(){var normalized=PartnerFormSupport.normalize(input(""),schema);assertThat(normalized.fields().get("name")).isEqualTo("");assertThat(normalized.options().getFirst().price()).isEqualTo("0");assertThat(normalized.options().getFirst().quantity()).isEqualTo("0");PartnerFormSupport.validate(input("상품"),schema);}
    @Test void refusesRemoteIdentifierAndRawSourceFields(){var i=input("상품");var unsafe=new PartnerEditor.Input(Map.of("spdNo","123"),i.options(),i.images(),i.description(),i.noticeType(),i.notices(),i.certifications());assertThatThrownBy(()->PartnerFormSupport.normalize(unsafe,schema)).hasMessageContaining("지원하지 않는");}
    @Test void rejectsDuplicateUuidAndBlob(){var i=input("상품");assertThatThrownBy(()->PartnerFormSupport.normalize(new PartnerEditor.Input(i.fields(),List.of(i.options().getFirst(),i.options().getFirst()),i.images(),i.description(),i.noticeType(),i.notices(),i.certifications()),schema)).hasMessageContaining("중복");var image=new PartnerEditor.Image(i.images().getFirst().id(),null,"blob:local",true,0);assertThatThrownBy(()->PartnerFormSupport.normalize(new PartnerEditor.Input(i.fields(),i.options(),List.of(image),i.description(),i.noticeType(),i.notices(),i.certifications()),schema)).hasMessageContaining("HTTPS");}
    @Test void rebaseDetectsOnlyChangedFieldConflict(){var changes=PartnerFormSupport.diff(input("before"),input("wanted"),json);var conflict=PartnerFormSupport.rebase(input("before"),input("external"),changes,json);assertThat(conflict.conflicts()).hasSize(1);assertThat(conflict.conflicts().getFirst().path()).isEqualTo("partner.fields.name");assertThat(PartnerFormSupport.rebase(input("before"),input("wanted"),changes,json).changes()).isEmpty();}
    @Test void rejectsMalformedAndDuplicateEditPaths(){assertThatThrownBy(()->PartnerFormSupport.apply(input("a"),List.of(new MarketplaceEditing.Change(null,null,"x")),json)).hasMessageContaining("변경 항목");var c=new MarketplaceEditing.Change("partner.fields.name",null,"");assertThatThrownBy(()->PartnerFormSupport.apply(input("a"),List.of(c,c),json)).hasMessageContaining("변경 항목");assertThat(PartnerFormSupport.apply(input("a"),List.of(c),json).fields().get("name")).isEqualTo("");}
    @Test void draftBoundaryRejectsMalformedNestedInputBeforeAssetPinning(){var i=input("상품");var images=new ArrayList<PartnerEditor.Image>();images.add(null);assertThatThrownBy(()->PartnerFormSupport.structure(new PartnerEditor.Input(i.fields(),i.options(),images,i.description(),i.noticeType(),i.notices(),i.certifications()))).hasMessageContaining("입력 항목 수");assertThatThrownBy(()->PartnerFormSupport.structure(new PartnerEditor.Input(Map.of("source",Map.of("spdNo","untrusted")),i.options(),i.images(),i.description(),i.noticeType(),i.notices(),i.certifications()))).hasMessageContaining("입력 형식");}
    @Test void preservesLegacyDraftRecordConstructors() {var esm=new MarketplaceDrafts.Esm("2","","","","",List.of(),List.of());assertThat(esm.editorInput()).isNull();assertThat(new MarketplaceDrafts.Lotteon("brand").editorState()).isNull();}
}
